// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.content.Contextimport android.content.Intentimport android.content.pm.PackageManagerimport android.net.ConnectivityManagerimport android.net.wifi.WifiManagerimport android.nfc.NfcAdapterimport android.os.Buildimport android.provider.Settingsimport com.roshan.persona.brain.skill.LocationModeimport com.roshan.persona.system.util.SettingsHelper/** * NOUS — Extended Connectivity Services (Module 10 v2 — Step 10.6). * * Three more service interfaces for Review 1's new toggles: *  - Location (GPS mode) *  - Tethering (Wi-Fi hotspot) *  - NFC * * Mirrors the design of [ConnectivityServices.kt] — thin interfaces for * testability, Android impls that wrap the real system services. * * ## API level constraints (per strategy v2 §"Privacy & Security") * *  - **Location**: `Settings.Global.LOCATION_MODE` write requires *    `WRITE_SECURE_SETTINGS`. Regular apps fall back to opening *    `Settings.ACTION_LOCATION_SOURCE_SETTINGS`. * *  - **Tethering**: `ConnectivityManager.startTethering` requires *    `CHANGE_NETWORK_STATE`. Some carriers/OEMs block tethering entirely — *    `startTethering` throws `IllegalArgumentException` (caught and mapped *    to `Hardware.Unsupported`). * *  - **NFC**: `NfcAdapter.enable`/`disable` requires `WRITE_SECURE_SETTINGS`. *    Devices without `FEATURE_NFC` return `null` from `getDefaultAdapter`. *    Regular apps fall back to `Settings.ACTION_NFC_SETTINGS`. */// ──────────────────────────────────────────────────────────────────────────// Location service// ──────────────────────────────────────────────────────────────────────────/** * Wraps `Settings.Global.LOCATION_MODE` for [LocationHandler]. */interface LocationService {    /** Get the current location mode. */    fun getMode(): LocationMode    /**     * True if this app can toggle location mode programmatically.     *     * Requires `WRITE_SECURE_SETTINGS` — system apps, rooted, or ADB-granted.     */    fun canToggleDirectly(): Boolean    /**     * Set the location mode directly. Returns true on success.     *     * Always returns false if [canToggleDirectly] is false.     */    fun setMode(mode: LocationMode): Boolean    /**     * Open the Location Settings page.     *     * @return true if the page was launched successfully.     */    fun openSettingsPage(): Boolean}/** * Android [LocationService] backed by `Settings.Global`. */class AndroidLocationService(    private val context: Context,    private val settingsHelper: SettingsHelper,) : LocationService {    override fun getMode(): LocationMode = try {        when (Settings.Secure.getInt(            context.contentResolver,            Settings.Secure.LOCATION_MODE,            Settings.Secure.LOCATION_MODE_OFF,        )) {            Settings.Secure.LOCATION_MODE_HIGH_ACCURACY -> LocationMode.HIGH_ACCURACY            Settings.Secure.LOCATION_MODE_BATTERY_SAVING -> LocationMode.BATTERY_SAVING            Settings.Secure.LOCATION_MODE_SENSORS_ONLY -> LocationMode.SENSORS_ONLY            else -> LocationMode.OFF        }    } catch (t: Throwable) {        Timber.tag("AndroidLocationService").w("Failed to read location mode", t)        LocationMode.OFF    }    override fun canToggleDirectly(): Boolean = settingsHelper.canWriteSecureSettings()    override fun setMode(mode: LocationMode): Boolean {        if (!canToggleDirectly()) return false        return try {            // Note: Settings.Secure.LOCATION_MODE was deprecated in API 28 but            // still works for write when WRITE_SECURE_SETTINGS is granted.            // On API 28+, the recommended approach is LocationManager.setLocationEnabledForUser,            // which also requires WRITE_SECURE_SETTINGS.            val modeInt = when (mode) {                LocationMode.HIGH_ACCURACY -> Settings.Secure.LOCATION_MODE_HIGH_ACCURACY                LocationMode.BATTERY_SAVING -> Settings.Secure.LOCATION_MODE_BATTERY_SAVING                LocationMode.SENSORS_ONLY -> Settings.Secure.LOCATION_MODE_SENSORS_ONLY                LocationMode.OFF -> Settings.Secure.LOCATION_MODE_OFF            }            Settings.Secure.putInt(                context.contentResolver,                Settings.Secure.LOCATION_MODE,                modeInt,            )            true        } catch (t: SecurityException) {            Timber.tag("AndroidLocationService").w("WRITE_SECURE_SETTINGS not granted", t)            false        } catch (t: Throwable) {            Timber.tag("AndroidLocationService").w("setMode failed", t)            false        }    }    override fun openSettingsPage(): Boolean = try {        val intent = Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidLocationService").w("Failed to open location settings", t)        false    }}// ──────────────────────────────────────────────────────────────────────────// Tethering service// ──────────────────────────────────────────────────────────────────────────/** * Wraps `ConnectivityManager` tethering methods for [TetheringHandler]. * * Note: Android's tethering API is messy. `startTethering` is hidden behind * a system API; the public `ConnectivityManager.startTethering` requires * `CHANGE_NETWORK_STATE` but throws `IllegalArgumentException` on devices * where tethering is carrier-blocked. On API 30+, the recommended approach * is `TetheringManager.startTethering` (also system API). * * This interface abstracts the mess — the handler doesn't care which API * path the impl uses. */interface TetheringService {    /** True if the device supports Wi-Fi tethering (some carriers block it). */    fun isTetheringSupported(): Boolean    /**     * True if Wi-Fi tethering is currently active.     *     * Best-effort — Android doesn't expose a clean API for this. Returns     * false if the state can't be determined.     */    fun isTetheringActive(): Boolean    /**     * Start Wi-Fi tethering. Returns true if the request was accepted.     *     * Note: success means "request accepted", not "tethering is now active" —     * the actual state change is async (via `TetheringManager` callback).     *     * @throws IllegalArgumentException if tethering is unsupported by carrier/OEM.     */    fun startTethering(): Boolean    /**     * Stop Wi-Fi tethering. Returns true on success.     */    fun stopTethering(): Boolean}/** * Android [TetheringService] backed by [ConnectivityManager]. * * Uses the deprecated `startTethering(int, boolean, callback)` API which * still works on most devices. On API 30+, the new `TetheringManager` API * is preferred but requires `TETHER_PRIVILEGED` permission (system apps only). * * For broad compatibility, we use the legacy API and catch * `IllegalArgumentException` for carrier-blocked tethering. */class AndroidTetheringService(    private val context: Context,) : TetheringService {    /**     * Access TetheringManager via reflection.     *     * ConnectivityManager's tethering methods were removed in API 30+.     * The replacement is TetheringManager (android.net.TetheringManager),     * which is a hidden/system API accessed via:     *   context.getSystemService(Class.forName("android.net.TetheringManager"))     *     * Strategy §10: real Android API usage — TetheringManager is the real     * system service, not a stub.     */    private val tetheringManager: Any? by lazy {        try {            val cls = Class.forName("android.net.TetheringManager")            context.getSystemService(cls)        } catch (t: Throwable) {            Timber.tag("AndroidTetheringService").w("TetheringManager not available", t)            null        }    }    override fun isTetheringSupported(): Boolean = try {        val mgr = tetheringManager ?: return false        val method = mgr.javaClass.getMethod("isTetheringSupported")        method.invoke(mgr) as? Boolean ?: false    } catch (t: Throwable) {        Timber.tag("AndroidTetheringService").w("isTetheringSupported failed", t)        false    }    override fun isTetheringActive(): Boolean {        // The legacy ConnectivityManager.getTetheredIfaces() was removed in API 30.        // The replacement is TetheringManager.getTetheredInterfaces() (API 30+) —        // also a @SystemApi, accessed reflectively here. As a final fallback,        // try the legacy getTetheredIfaces() on TetheringManager (deprecated but        // present on some OEM ROMs).        val mgr = tetheringManager ?: return false        // Try the modern API 30+ method first.        val ifaces = invokeTetheredInterfacesMethod(mgr, "getTetheredInterfaces")            ?: invokeTetheredInterfacesMethod(mgr, "getTetheredIfaces")            ?: return false        return ifaces.isNotEmpty()    }    /** Reflectively invoke a no-arg method on the tethering manager returning String[]. */    private fun invokeTetheredInterfacesMethod(mgr: Any, methodName: String): Array<*>? {        return try {            val method = mgr.javaClass.getMethod(methodName)            @Suppress("UNCHECKED_CAST")            method.invoke(mgr) as? Array<*>        } catch (e: NoSuchMethodException) {            // Expected on API levels where the method doesn't exist — fall through.            null        } catch (t: Throwable) {            Timber.tag("AndroidTetheringService").w("Failed to invoke $methodName", t)            null        }    }    override fun startTethering(): Boolean {        return try {            val mgr = tetheringManager ?: return false            // TETHERING_WIFI = 0            val startTetheringMethod = mgr.javaClass.getMethod(                "startTethering",                Int::class.javaPrimitiveType,                Boolean::class.javaPrimitiveType,                Class.forName("android.net.TetheringManager\$StartTetheringCallback"),            )            // Create a no-op callback via proxy            val callbackClass = Class.forName("android.net.TetheringManager\$StartTetheringCallback")            val callback = java.lang.reflect.Proxy.newProxyInstance(                callbackClass.classLoader,                arrayOf(callbackClass),            ) { _, method, _ ->                when (method.name) {                    "onTetheringStarted" -> Unit                    "onTetheringFailed" -> Unit                    else -> null                }            }            startTetheringMethod.invoke(mgr, 0, false, callback)            true        } catch (t: SecurityException) {            Timber.tag("AndroidTetheringService").w("CHANGE_NETWORK_STATE not granted", t)            false        } catch (t: Throwable) {            Timber.tag("AndroidTetheringService").w("startTethering failed", t)            false        }    }    override fun stopTethering(): Boolean {        return try {            val mgr = tetheringManager ?: return false            val method = mgr.javaClass.getMethod("stopTethering", Int::class.javaPrimitiveType)            method.invoke(mgr, 0)  // TETHERING_WIFI = 0            true        } catch (t: Throwable) {            Timber.tag("AndroidTetheringService").w("stopTethering failed", t)            false        }    }}// ──────────────────────────────────────────────────────────────────────────// NFC service// ──────────────────────────────────────────────────────────────────────────/** * Wraps `NfcAdapter` for [NfcHandler]. */interface NfcService {    /** True if the device has an NFC radio (`FEATURE_NFC`). */    fun isAvailable(): Boolean    /** True if NFC is currently enabled. */    fun isEnabled(): Boolean    /**     * True if this app can toggle NFC programmatically.     *     * Requires `WRITE_SECURE_SETTINGS`. `NfcAdapter.enable`/`disable` are     * hidden system APIs that throw `UnsupportedOperationException` on     * non-system apps.     */    fun canToggleDirectly(): Boolean    /**     * Enable/disable NFC. Returns true on success.     *     * Always returns false if [canToggleDirectly] is false.     */    fun setEnabled(enabled: Boolean): Boolean    /**     * Open the NFC Settings page.     *     * @return true if the page was launched successfully.     */    fun openSettingsPage(): Boolean}/** * Android [NfcService] backed by [NfcAdapter] + [PackageManager]. */class AndroidNfcService(    private val context: Context,    private val settingsHelper: SettingsHelper,) : NfcService {    private val adapter: NfcAdapter? by lazy {        try {            NfcAdapter.getDefaultAdapter(context)        } catch (t: Throwable) {            null        }    }    override fun isAvailable(): Boolean = try {        context.packageManager.hasSystemFeature(PackageManager.FEATURE_NFC)    } catch (t: Throwable) {        false    }    override fun isEnabled(): Boolean = try {        adapter?.isEnabled ?: false    } catch (t: Throwable) {        false    }    override fun canToggleDirectly(): Boolean = settingsHelper.canWriteSecureSettings()    override fun setEnabled(enabled: Boolean): Boolean {        if (!canToggleDirectly()) return false        return try {            // NfcAdapter.enable() and disable() are hidden APIs that throw            // UnsupportedOperationException on non-system apps. With            // WRITE_SECURE_SETTINGS (ADB/root/system), they work via reflection.            val method = NfcAdapter::class.java.getDeclaredMethod(                if (enabled) "enable" else "disable"            )            method.isAccessible = true            method.invoke(adapter)            true        } catch (e: UnsupportedOperationException) {            Timber.tag("AndroidNfcService").w("NFC toggle not supported", e)            throw e        } catch (t: Throwable) {            Timber.tag("AndroidNfcService").w("setEnabled failed", t)            false        }    }    override fun openSettingsPage(): Boolean = try {        val intent = Intent(Settings.ACTION_NFC_SETTINGS)            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidNfcService").w("Failed to open NFC settings", t)        false    }}